/* timer_settime(2) - Example showing periodic timer setup */
#include <time.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

timer_t global_timerid;

// Signal handler function triggered when the timer expires
void handler(int sig, siginfo_t *si, void *uc) {
    static int count = 0;
    printf("[%ld] Timer event triggered (count: %d)\n", (long)time(NULL), ++count);

    // Stop after 3 ticks
    if (count >= 3) {
        struct itimerspec stop_spec = {{0, 0}, {0, 0}};
        if (timer_settime(global_timerid, 0, &stop_spec, NULL) == -1) {
            perror("timer_settime stop");
            exit(EXIT_FAILURE);
        }
        printf("Timer disarmed. Exiting.\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    struct sigevent sev;
    struct itimerspec its;

    // 1. Setup signal handling for a real-time signal
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // 2. Configure sigevent to deliver SIGRTMIN upon expiration
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &global_timerid;

    // 3. Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return 1;
    }

    // 4. Define timer settings: Initial delay 1s, repeat every 500ms
    its.it_value.tv_sec = 1;      
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec = 0;   
    its.it_interval.tv_nsec = 500000000; // 0.5 seconds

    printf("Setting up periodic timer. Initial 1s, Interval 0.5s.\n");

    // 5. Arm the timer using timer_settime()
    if (timer_settime(global_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime start");
        // Cleanup on failure
        timer_delete(global_timerid);
        return 1;
    }

    // Wait for signals (the handler contains the exit logic)
    for (;;) {
        pause();
    }

    // Not reached due to handler exit, but good practice
    timer_delete(global_timerid);
    return 0;
}
